// 1. Input Validation & Fault Latching
if (wa_input.requested_torque_nm == NULL || wa_input.axes == NULL) {
    wa_output.mode = WA_FAULT;
    wa_output.wheel_torque_nm[0] = 0.0;
    wa_output.wheel_torque_nm[1] = 0.0;
    wa_output.wheel_torque_nm[2] = 0.0;
    wa_output.achieved_torque_nm.x = 0.0;
    wa_output.achieved_torque_nm.y = 0.0;
    wa_output.achieved_torque_nm.z = 0.0;
    wa_output.residual_torque_nm.x = 0.0;
    wa_output.residual_torque_nm.y = 0.0;
    wa_output.residual_torque_nm.z = 0.0;
    wa_output.residual_norm_nm = 0.0;
    wa_output.saturation_mask = 0U;
    wa_output.slew_mask = 0U;
    wa_output.unavailable_mask = 0U;
    return;
}

if (!adcs_is_finite_vec3(wa_input.requested_torque_nm)) {
    wa_output.mode = WA_FAULT;
    wa_output.wheel_torque_nm[0] = 0.0;
    wa_output.wheel_torque_nm[1] = 0.0;
    wa_output.wheel_torque_nm[2] = 0.0;
    wa_output.achieved_torque_nm.x = 0.0;
    wa_output.achieved_torque_nm.y = 0.0;
    wa_output.achieved_torque_nm.z = 0.0;
    wa_output.residual_torque_nm.x = 0.0;
    wa_output.residual_torque_nm.y = 0.0;
    wa_output.residual_torque_nm.z = 0.0;
    wa_output.residual_norm_nm = 0.0;
    wa_output.saturation_mask = 0U;
    wa_output.slew_mask = 0U;
    wa_output.unavailable_mask = 0U;
    return;
}

if (wa_input.axis_count != 3U) {
    wa_output.mode = WA_FAULT;
    wa_output.wheel_torque_nm[0] = 0.0;
    wa_output.wheel_torque_nm[1] = 0.0;
    wa_output.wheel_torque_nm[2] = 0.0;
    wa_output.achieved_torque_nm.x = 0.0;
    wa_output.achieved_torque_nm.y = 0.0;
    wa_output.achieved_torque_nm.z = 0.0;
    wa_output.residual_torque_nm.x = 0.0;
    wa_output.residual_torque_nm.y = 0.0;
    wa_output.residual_torque_nm.z = 0.0;
    wa_output.residual_norm_nm = 0.0;
    wa_output.saturation_mask = 0U;
    wa_output.slew_mask = 0U;
    wa_output.unavailable_mask = 0U;
    return;
}

// Validate axes are finite and normalize them
adcs_vec3_t normalized_axes[3];
for (size_t i = 0; i < 3; ++i) {
    if (!adcs_is_finite_vec3(&wa_input.axes[i])) {
        wa_output.mode = WA_FAULT;
        wa_output.wheel_torque_nm[0] = 0.0;
        wa_output.wheel_torque_nm[1] = 0.0;
        wa_output.wheel_torque_nm[2] = 0.0;
        wa_output.achieved_torque_nm.x = 0.0;
        wa_output.achieved_torque_nm.y = 0.0;
        wa_output.achieved_torque_nm.z = 0.0;
        wa_output.residual_torque_nm.x = 0.0;
        wa_output.residual_torque_nm.y = 0.0;
        wa_output.residual_torque_nm.z = 0.0;
        wa_output.residual_norm_nm = 0.0;
        wa_output.saturation_mask = 0U;
        wa_output.slew_mask = 0U;
        wa_output.unavailable_mask = 0U;
        return;
    }
    if (adcs_vec3_normalize(&wa_input.axes[i], ADCS_EPS_NORM, &normalized_axes[i]) != ADCS_OK) {
        wa_output.mode = WA_FAULT;
        wa_output.wheel_torque_nm[0] = 0.0;
        wa_output.wheel_torque_nm[1] = 0.0;
        wa_output.wheel_torque_nm[2] = 0.0;
        wa_output.achieved_torque_nm.x = 0.0;
        wa_output.achieved_torque_nm.y = 0.0;
        wa_output.achieved_torque_nm.z = 0.0;
        wa_output.residual_torque_nm.x = 0.0;
        wa_output.residual_torque_nm.y = 0.0;
        wa_output.residual_torque_nm.z = 0.0;
        wa_output.residual_norm_nm = 0.0;
        wa_output.saturation_mask = 0U;
        wa_output.slew_mask = 0U;
        wa_output.unavailable_mask = 0U;
        return;
    }
}

// Validate config parameters
if (!isfinite(wa_config.wheel_limit_nm[0]) || !isfinite(wa_config.wheel_limit_nm[1]) || !isfinite(wa_config.wheel_limit_nm[2]) ||
    wa_config.wheel_limit_nm[0] <= 0.0 || wa_config.wheel_limit_nm[1] <= 0.0 || wa_config.wheel_limit_nm[2] <= 0.0 ||
    !isfinite(wa_config.max_wheel_slew_nm_per_cycle[0]) || !isfinite(wa_config.max_wheel_slew_nm_per_cycle[1]) || !isfinite(wa_config.max_wheel_slew_nm_per_cycle[2]) ||
    wa_config.max_wheel_slew_nm_per_cycle[0] <= 0.0 || wa_config.max_wheel_slew_nm_per_cycle[1] <= 0.0 || wa_config.max_wheel_slew_nm_per_cycle[2] <= 0.0 ||
    wa_config.release_cycles < 1U || wa_config.release_cycles > 20U ||
    wa_config.restore_cycles < 1U || wa_config.restore_cycles > 20U) {
    wa_output.mode = WA_FAULT;
    wa_output.wheel_torque_nm[0] = 0.0;
    wa_output.wheel_torque_nm[1] = 0.0;
    wa_output.wheel_torque_nm[2] = 0.0;
    wa_output.achieved_torque_nm.x = 0.0;
    wa_output.achieved_torque_nm.y = 0.0;
    wa_output.achieved_torque_nm.z = 0.0;
    wa_output.residual_torque_nm.x = 0.0;
    wa_output.residual_torque_nm.y = 0.0;
    wa_output.residual_torque_nm.z = 0.0;
    wa_output.residual_norm_nm = 0.0;
    wa_output.saturation_mask = 0U;
    wa_output.slew_mask = 0U;
    wa_output.unavailable_mask = 0U;
    return;
}

// 2. Enable Check
if (!wa_input.enable) {
    wa_output.mode = WA_NORMAL;
    wa_output.clean_count = 0U;
    wa_output.restore_count = 0U;
    wa_state.previous_wheel_torque_nm[0] = 0.0;
    wa_state.previous_wheel_torque_nm[1] = 0.0;
    wa_state.previous_wheel_torque_nm[2] = 0.0;

    wa_output.wheel_torque_nm[0] = 0.0;
    wa_output.wheel_torque_nm[1] = 0.0;
    wa_output.wheel_torque_nm[2] = 0.0;
    wa_output.achieved_torque_nm.x = 0.0;
    wa_output.achieved_torque_nm.y = 0.0;
    wa_output.achieved_torque_nm.z = 0.0;
    wa_output.residual_torque_nm = *wa_input.requested_torque_nm;
    wa_output.residual_norm_nm = adcs_vec3_norm(&wa_output.residual_torque_nm);
    wa_output.saturation_mask = 0U;
    wa_output.slew_mask = 0U;
    wa_output.unavailable_mask = 0U;
    return;
}

// 3. Determine Available Wheels and Mask
unint32 available_mask = wa_input.available_mask & 0x7U;
unint32 unavailable_mask = 0U;
int available_count = 0;

for (int i = 0; i < 3; ++i) {
    if ((available_mask & (1U << i))) {
        available_count++;
    } else {
        unavailable_mask |= (1U << i);
    }
}

// 4. Orthogonality Check on Available Axes
int avail_idx[3];
int avail_cnt = 0;
for(int i=0; i<3; ++i) {
    if(available_mask & (1U << i)) {
        avail_idx[avail_cnt++] = i;
    }
}

int orthogonal_ok = 1;
for(int i=0; i<avail_cnt; ++i) {
    for(int j=i+1; j<avail_cnt; ++j) {
        double dot = adcs_vec3_dot(&normalized_axes[avail_idx[i]], &normalized_axes[avail_idx[j]]);
        if (fabs(dot) > ADCS_EPS_COLLINEAR) {
            orthogonal_ok = 0;
            break;
        }
    }
    if(!orthogonal_ok) break;
}

if (!orthogonal_ok) {
    wa_output.mode = WA_FAULT;
    wa_output.wheel_torque_nm[0] = 0.0;
    wa_output.wheel_torque_nm[1] = 0.0;
    wa_output.wheel_torque_nm[2] = 0.0;
    wa_output.achieved_torque_nm.x = 0.0;
    wa_output.achieved_torque_nm.y = 0.0;
    wa_output.achieved_torque_nm.z = 0.0;
    wa_output.residual_torque_nm.x = 0.0;
    wa_output.residual_torque_nm.y = 0.0;
    wa_output.residual_torque_nm.z = 0.0;
    wa_output.residual_norm_nm = 0.0;
    wa_output.saturation_mask = 0U;
    wa_output.slew_mask = 0U;
    wa_output.unavailable_mask = unavailable_mask;
    return;
}

// 5. Torque Allocation
double raw_torques[3] = {0.0};
for (int i = 0; i < 3; ++i) {
    if (!(available_mask & (1U << i))) {
        wa_output.wheel_torque_nm[i] = 0.0;
        continue;
    }
    raw_torques[i] = adcs_vec3_dot(wa_input.requested_torque_nm, &normalized_axes[i]);
}

// 6. Magnitude Limiting
unint32 saturation_mask = 0U;
double limited_torques[3] = {0.0};
for (int i = 0; i < 3; ++i) {
    if (!(available_mask & (1U << i))) {
        limited_torques[i] = 0.0;
        continue;
    }
    double mag = raw_torques[i];
    double limit = wa_config.wheel_limit_nm[i];
    if (mag > limit) {
        limited_torques[i] = limit;
        saturation_mask |= (1U << i);
    } else if (mag < -limit) {
        limited_torques[i] = -limit;
        saturation_mask |= (1U << i);
    } else {
        limited_torques[i] = mag;
    }
}

// 7. Slew Rate Limiting
unint32 slew_mask = 0U;
double final_torques[3] = {0.0};
for (int i = 0; i < 3; ++i) {
    if (!(available_mask & (1U << i))) {
        final_torques[i] = 0.0;
        continue;
    }
    double prev = wa_state.previous_wheel_torque_nm[i];
    double delta = limited_torques[i] - prev;
    double max_slew = wa_config.max_wheel_slew_nm_per_cycle[i];

    if (delta > max_slew) {
        final_torques[i] = prev + max_slew;
        slew_mask |= (1U << i);
    } else if (delta < -max_slew) {
        final_torques[i] = prev - max_slew;
        slew_mask |= (1U << i);
    } else {
        final_torques[i] = limited_torques[i];
    }
}

// Update State Previous Torques
for (int i = 0; i < 3; ++i) {
    wa_state.previous_wheel_torque_nm[i] = final_torques[i];
}

// 8. Output Assignment
wa_output.wheel_torque_nm[0] = final_torques[0];
wa_output.wheel_torque_nm[1] = final_torques[1];
wa_output.wheel_torque_nm[2] = final_torques[2];
wa_output.saturation_mask = saturation_mask;
wa_output.slew_mask = slew_mask;
wa_output.unavailable_mask = unavailable_mask;

// 9. Reconstruct Achieved Torque
adcs_vec3_t achieved = {0.0, 0.0, 0.0};
for (int i = 0; i < 3; ++i) {
    if (available_mask & (1U << i)) {
        adcs_vec3_t term = adcs_vec3_scale(&normalized_axes[i], final_torques[i]);
        achieved = adcs_vec3_add(&achieved, &term);
    }
}
wa_output.achieved_torque_nm = achieved;

// Residual
wa_output.residual_torque_nm = adcs_vec3_sub(wa_input.requested_torque_nm, &achieved);
wa_output.residual_norm_nm = adcs_vec3_norm(&wa_output.residual_torque_nm);

// 10. State Machine Logic
int any_limited = (saturation_mask != 0U) || (slew_mask != 0U);
int all_available = (unavailable_mask == 0U);
int all_healthy = all_available && !any_limited;

switch (wa_output.mode) {
    case WA_LIMITED:
        if (all_healthy) {
            wa_output.clean_count++;
            if (wa_output.clean_count >= wa_config.release_cycles) {
                wa_output.mode = WA_NORMAL;
                wa_output.clean_count = 0U;
            }
        } else {
            wa_output.clean_count = 0U;
        }
        break;

    case WA_RECOVERING:
        if (all_healthy) {
            wa_output.restore_count++;
            if (wa_output.restore_count >= wa_config.restore_cycles) {
                wa_output.mode = WA_NORMAL;
                wa_output.restore_count = 0U;
            }
        } else {
            if (!all_available) {
                wa_output.mode = WA_DEGRADED;
                wa_output.restore_count = 0U;
            } else {
                if (any_limited) {
                    wa_output.mode = WA_LIMITED;
                    wa_output.clean_count = 0U;
                    wa_output.restore_count = 0U;
                } else {
                     wa_output.mode = WA_LIMITED;
                     wa_output.clean_count = 0U;
                     wa_output.restore_count = 0U;
                }
            }
        }
        break;

    case WA_DEGRADED:
        if (all_available) {
            wa_output.mode = WA_RECOVERING;
            wa_output.restore_count = 0U;
        }
        break;

    case WA_NORMAL:
        if (!all_available) {
            wa_output.mode = WA_DEGRADED;
            wa_output.clean_count = 0U;
            wa_output.restore_count = 0U;
        } else if (any_limited) {
            wa_output.mode = WA_LIMITED;
            wa_output.clean_count = 0U;
            wa_output.restore_count = 0U;
        }
        break;

    case WA_FAULT:
    default:
        break;
}

