int all_available = (unavailable_mask == 0U);
int all_healthy = all_available && !any_limited;

switch (wa_output.mode) {
    case WA_LIMITED:
        if (all_healthy) {
            wa_output.clean_count++;
            if (wa_output.clean_count >= wa_config.release_cycles) {
                wa_output.mode = WA_NORMAL;
                wa_output.clean_count = 0U;
            }
