        break;

    case WA_DEGRADED:
        if (all_available) {
            wa_output.mode = WA_RECOVERING;
            wa_output.restore_count = 0U;
        }
        break;

    case WA_NORMAL:
        if (!all_available) {
            wa_output.mode = WA_DEGRADED;
            wa_output.clean_count = 0U;
            wa_output.restore_count = 0U;
        } else if (any_limited) {
            wa_output.mode = WA_LIMITED;
            wa_output.clean_count = 0U;
            wa_output.restore_count = 0U;
        }
        break;

    case WA_FAULT:
    default:
        break;
}

